#!/app/.venv/bin/python
import sys
import os
if os.environ['AUDIT_VARIANT'] in {'money', 'combined'}:
    sys.path.insert(0, '/audit/money')
sys.path[:0] = ['/candidate/apps/data-plane/src', '/candidate/lib/runtime/src', '/aiohttp-deps']
import cProfile
import json
import logging
import os
import signal
import time
from pathlib import Path

if os.environ['AUDIT_VARIANT'] == 'coalesce':
    import data_plane
    data_plane.__path__.insert(0, '/audit/coalesce/data_plane')

import data_plane.app
from data_plane.metrics import DataPlaneMetrics

variant = os.environ['AUDIT_VARIANT']
output = Path(os.environ['AUDIT_OUTPUT'])
if variant in {'no_logs', 'no_observability'}:
    configure = data_plane.app.configure_logger
    def quiet(logger, *, dev):
        configure(logger, dev=dev)
        logger.setLevel(logging.WARNING)
    data_plane.app.configure_logger = quiet
if variant in {'no_metrics', 'no_observability'}:
    for name in vars(DataPlaneMetrics):
        if name.startswith(('observe_', 'set_', 'relabel_')):
            setattr(DataPlaneMetrics, name, lambda *args, **kwargs: None)

if variant == 'exemplars_off':
    os.environ['OTEL_METRICS_EXEMPLAR_FILTER'] = 'always_off'
if variant in {'fast_json_logs', 'combined'}:
    import airmux_runtime.observability as obs
    from datetime import UTC, datetime
    from pydantic_core import to_json
    def format_record(self, record):
        payload = {'timestamp': datetime.now(tz=UTC).isoformat(), 'level': record.levelname.lower(), 'logger': record.name, 'event': getattr(record, 'event', 'log'), 'message': record.getMessage()}
        if request_id := obs._request_id.get():
            payload['request_id'] = request_id
        payload.update(getattr(record, 'fields', {}))
        if record.exc_info:
            payload['exception'] = self.formatException(record.exc_info)
        return to_json(payload, fallback=str).decode()
    obs.JsonFormatter.format = format_record
if variant == 'no_log_io':
    import airmux_runtime.observability as obs
    class FormatOnly(logging.Handler):
        def emit(self, record):
            self.format(record)
    def format_only_logger(logger, *, dev):
        if not logger.handlers:
            handler=FormatOnly()
            handler.setFormatter(obs.JsonFormatter())
            logger.addHandler(handler)
            logger.setLevel(logging.INFO)
    data_plane.app.configure_logger = format_only_logger

if variant in {'batch_logs', 'combined'}:
    import asyncio
    import atexit
    import sys
    import airmux_runtime.observability as obs
    class BatchedHandler(logging.StreamHandler):
        def __init__(self):
            super().__init__()
            self.lines=[]
            self.timer=None
        def emit(self, record):
            self.lines.append(self.format(record)+'\n')
            if len(self.lines)>=100 or record.levelno>=logging.ERROR:
                self.flush()
            elif self.timer is None:
                try:
                    self.timer=asyncio.get_running_loop().call_later(0.1,self.flush)
                except RuntimeError:
                    self.flush()
        def flush(self):
            self.acquire()
            try:
                if self.timer is not None:
                    self.timer.cancel()
                    self.timer=None
                if self.lines:
                    self.stream.write(''.join(self.lines))
                    self.lines.clear()
                    self.stream.flush()
            finally:
                self.release()
    def buffered_logger(logger, *, dev):
        if not logger.handlers:
            handler=BatchedHandler()
            handler.setFormatter(obs.JsonFormatter())
            logger.addHandler(handler)
            logger.setLevel(logging.INFO)
    data_plane.app.configure_logger=buffered_logger

if variant in {'native_metrics', 'combined'}:
    import data_plane.metrics
    from prometheus_probe import PrometheusTelemetry
    data_plane.metrics.MetricsTelemetry=PrometheusTelemetry

counts = {}
if os.environ.get('AUDIT_PHASES') == '1':
    import data_plane.proxy as proxy
    import data_plane.http as http
    import data_plane.metering as metering
    from data_plane.egress.anthropic import AnthropicAdapter
    from data_plane.ingress.anthropic import AnthropicIngress
    from airmux_runtime.observability import JsonFormatter
    def timed(owner, name, label):
        function = getattr(owner, name)
        counts[label + '_cpu_ns'] = 0
        counts[label + '_calls'] = 0
        def measured(*args, **kwargs):
            started = time.thread_time_ns()
            try:
                return function(*args, **kwargs)
            finally:
                counts[label + '_cpu_ns'] += time.thread_time_ns() - started
                counts[label + '_calls'] += 1
        setattr(owner, name, measured)
    for owner, name, label in (
        (http, 'authenticate_request', 'auth'),
        (http.ResponseHeadersMiddleware, '_route', 'route_label'),
        (proxy, '_parse', 'parse'),
        (proxy, 'plan_routes', 'routing'),
        (proxy, 'reconcile', 'reconcile'),
        (proxy, '_transform', 'request_translation'),
        (AnthropicAdapter, 'transform_response', 'response_translation'),
        (AnthropicIngress, 'render_response', 'render_response'),
        (proxy, 'usage_event', 'usage_accounting_including_log'),
        (metering, 'cost_breakdown', 'pricing'),
        (metering, 'log_event', 'usage_log'),
        (JsonFormatter, 'format', 'log_format'),
    ):
        timed(owner, name, label)
    for name in vars(DataPlaneMetrics):
        if name.startswith('observe_'):
            timed(DataPlaneMetrics, name, name)
signal.signal(signal.SIGUSR2, lambda *_: output.with_suffix('.counts.json').write_text(json.dumps(counts)))
profile = cProfile.Profile(timer=time.thread_time)
profiling = False
if os.environ.get('AUDIT_PROFILE') == '1':
    def toggle(*_):
        global profiling
        if profiling:
            profile.disable()
            profile.dump_stats(str(output.with_suffix('.prof')))
        else:
            profile.enable()
        profiling = not profiling
    signal.signal(signal.SIGUSR1, toggle)
from cli.main import main
main()

