from prometheus_client import CollectorRegistry, Counter, Gauge, Histogram, disable_created_metrics, generate_latest
from prometheus_client.exposition import CONTENT_TYPE_LATEST

class Instrument:
    def __init__(self, kind, name, description, registry):
        self.kind=kind
        self.name=name
        self.description=description
        self.registry=registry
        self.collector=None
        self.children={}
        self.label_names=()
    def _child(self, attributes):
        if self.collector is None:
            self.label_names=tuple(attributes)
            kwargs={'buckets':(0,5,10,25,50,75,100,250,500,750,1000,2500,5000,7500,10000)} if self.kind is Histogram else {}
            self.collector=self.kind(self.name,self.description,self.label_names,registry=self.registry,**kwargs)
        key=tuple(attributes[name] for name in self.label_names)
        child=self.children.get(key)
        if child is None:
            child=self.collector.labels(*key) if key else self.collector
            self.children[key]=child
        return child
    def add(self, value, attributes):
        self._child(attributes).inc(value)
    def record(self, value, attributes):
        self._child(attributes).observe(value)

class PrometheusTelemetry:
    content_type=CONTENT_TYPE_LATEST
    def __init__(self, service_name):
        disable_created_metrics()
        self.registry=CollectorRegistry(auto_describe=True)
        self.meter=self
    def create_counter(self,name,description):
        return Instrument(Counter,name,description,self.registry)
    def create_up_down_counter(self,name,description):
        return Instrument(Gauge,name,description,self.registry)
    def create_histogram(self,name,description):
        return Instrument(Histogram,name,description,self.registry)
    def observable_gauge(self,name,description,value):
        Gauge(name,description,registry=self.registry).set_function(value)
    def render(self):
        return generate_latest(self.registry)
    def shutdown(self):
        pass

