import hashlib
import json
import pstats
import statistics
from pathlib import Path
from prometheus_client.parser import text_string_to_metric_families

root=Path.cwd()
audit=Path('/private/tmp/airmux-aiohttp-cpu-leads')

def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()

def slim(value):
    if isinstance(value,dict): return {k:slim(v) for k,v in value.items() if k!='samples'}
    if isinstance(value,list): return [slim(v) for v in value]
    return value

def summarize(trials):
    baseline={t['round']:t for t in trials if t['variant']=='baseline'}
    result={}
    for variant in dict.fromkeys(t['variant'] for t in trials):
        group=[t for t in trials if t['variant']==variant]
        result[variant]={
            'cpu_us_per_request':statistics.median(t['cpu_us_per_request'] for t in group),
            'rps':statistics.median(t['rps'] for t in group),
            'cpu_percent_one_core':statistics.median(t['resources']['cpu_percent_one_core'] for t in group),
            'paired_cpu_savings_us':[baseline[t['round']]['cpu_us_per_request']-t['cpu_us_per_request'] for t in group],
            'paired_cpu_savings_pct':[(1-t['cpu_us_per_request']/baseline[t['round']]['cpu_us_per_request'])*100 for t in group],
        }
    return result

def metric_samples(path):
    return {(s.name,tuple(sorted(s.labels.items()))):s.value for family in text_string_to_metric_families(path.read_text()) for s in family.samples}

metrics_parity=[]
log_parity=[]
for number in (1,2,3):
    directory=audit/'candidates'
    baseline=metric_samples(directory/f'r{number}-baseline/metrics.txt')
    for variant in ('native_metrics','combined'):
        candidate=metric_samples(directory/f'r{number}-{variant}/metrics.txt')
        assert baseline.keys()==candidate.keys()
        differences=[(key,baseline[key],candidate[key]) for key in baseline if baseline[key]!=candidate[key] and not key[0].endswith('_sum') and 'timestamp' not in key[0] and 'last_adopted' not in key[0]]
        assert not differences,differences
        metrics_parity.append({'round':number,'variant':variant,'matched_series':len(baseline)})
    for variant in ('baseline','money','batch_logs','native_metrics','combined'):
        usage=[json.loads(line) for line in (directory/f'r{number}-{variant}/gateway.log').read_text().splitlines() if line.startswith('{')]
        usage=[e for e in usage if e.get('event')=='usage_recorded']
        assert len(usage)==21002
        normalized=[{k:v for k,v in e.items() if k not in ('timestamp','request_id','latency_ms')} for e in usage]
        assert all(e==normalized[0] for e in normalized)
        if variant=='baseline':
            expected=normalized[0]
        assert normalized[0]==expected,(variant,normalized[0],expected)
        log_parity.append({'round':number,'variant':variant,'verified_records':len(usage),'payload':normalized[0]})

before=json.loads((audit/'money-before.json').read_text()); after=json.loads((audit/'money-after.json').read_text())
assert before['results']==after['results'] and before['schemas']==after['schemas']
money={'cases':len(before['results']),'result_sha256':hashlib.sha256(json.dumps(before['results']).encode()).hexdigest(),'schemas':before['schemas'],'before_timings_ns':before['timings_ns'],'after_timings_ns':after['timings_ns'],'contract_tests':(audit/'money-contract-tests.log').read_text()}
profile=pstats.Stats(str(audit/'profile/r1-baseline/diagnostic.prof'))
functions=[{'file':key[0],'line':key[1],'function':key[2],'calls':value[1],'own_cpu_s':value[2],'cumulative_cpu_s':value[3]} for key,value in sorted(profile.stats.items(),key=lambda i:-i[1][2])]
data={
    'baseline_commit':'9d6f10bac60de2e8ea313c1eb07159f75d4b39e2',
    'image_id':'sha256:949b35ffa05699e3e7d0e7f45b9d47c339a379ed99e263da8cf4056cd1387995',
    'configuration':{'workers':1,'cpus':4,'memory_gib':8,'network':'none','event_sink':'devnull','control_plane':False},
    'money_parity':money,'metrics_parity':metrics_parity,'log_parity':log_parity,
    'profile':{'total_calls':profile.total_calls,'total_profiled_cpu_s':profile.total_tt,'functions':functions[:80]},
    'experiments':{},
    'source_sha256':{str(path.relative_to(root)):digest(path) for prefix in ('apps/data-plane/src','lib/runtime/src','lib/contract/src') for path in sorted((root/prefix).rglob('*.py'))},
    'diagnostic_sources':{name:(audit/name).read_text() for name in ('gateway','run.py','comparison.py','streams.py','prometheus_probe.py','failure_probe.py','money_probe.py','money/contract/money.py','coalesce/data_plane/streaming.py','collect.py')},
    'raw_artifacts':str(audit),
}
for name in ('profile','phases','screen','candidates','cpu_saturation'):
    trials=json.loads((audit/name/'summary.json').read_text())
    assert all(not t['errors'] for t in trials)
